RECORDS = [
    {"id": "D", "rank": 30},
    {"id": "B", "rank": 20},
    {"id": "A", "rank": 10},
    {"id": "C", "rank": 20},
]


def stable_sorted_records(records):
    """Return a new list sorted by rank; equal ranks retain input order."""
    return sorted(records, key=lambda record: record["rank"])


def _validate_page_arguments(page_number, page_size):
    if type(page_number) is not int or page_number < 0:
        raise ValueError("page_number must be a nonnegative integer")
    if type(page_size) is not int or page_size <= 0:
        raise ValueError("page_size must be a positive integer")


def paginate_buggy(records, page_number, page_size):
    """Deliberate defect: positive pages start one record too early."""
    _validate_page_arguments(page_number, page_size)
    start = page_number * page_size
    if page_number > 0:
        start -= 1
    stop = start + page_size
    return records[start:stop]


def paginate_wrong_inclusive_end(records, page_number, page_size):
    """Deliberate wrong fix: includes one record beyond the page boundary."""
    _validate_page_arguments(page_number, page_size)
    start = page_number * page_size
    stop = start + page_size
    return records[start:stop + 1]


def paginate(records, page_number, page_size):
    """Return one zero-based, end-exclusive page."""
    _validate_page_arguments(page_number, page_size)
    start = page_number * page_size
    stop = start + page_size
    return records[start:stop]


def ids(records):
    return [record["id"] for record in records]

import unittest

from pagination_core import (
    RECORDS,
    ids,
    paginate,
    paginate_buggy,
    paginate_wrong_inclusive_end,
    stable_sorted_records,
)


class BugReproductionTests(unittest.TestCase):
    def test_second_page_actual_as_expected(self):
        ordered = stable_sorted_records(RECORDS)
        actual = ids(paginate_buggy(ordered, 1, 2))
        expected = ["C", "D"]
        # Intentionally fails: actual is passed first, expected second.
        self.assertListEqual(actual, expected)


class WrongFixTests(unittest.TestCase):
    def test_inclusive_end_is_rejected(self):
        ordered = stable_sorted_records(RECORDS)
        actual = ids(paginate_wrong_inclusive_end(ordered, 0, 2))
        expected = ["A", "B"]
        # Intentionally fails independently of the original defect.
        self.assertListEqual(actual, expected)


class CorrectPaginatorTests(unittest.TestCase):
    def setUp(self):
        self.ordered = stable_sorted_records(RECORDS)

    def test_stable_sorted_input(self):
        self.assertListEqual(ids(self.ordered), ["A", "B", "C", "D"])
        self.assertEqual(
            [record["rank"] for record in self.ordered],
            [10, 20, 20, 30],
        )

    def test_expected_pages_without_overlap_or_omission(self):
        page_zero = ids(paginate(self.ordered, 0, 2))
        page_one = ids(paginate(self.ordered, 1, 2))
        self.assertListEqual(page_zero, ["A", "B"])
        self.assertListEqual(page_one, ["C", "D"])
        self.assertListEqual(page_zero + page_one, ["A", "B", "C", "D"])
        self.assertEqual(set(page_zero).intersection(page_one), set())

    def test_partial_final_page_and_page_beyond_data(self):
        self.assertListEqual(ids(paginate(self.ordered, 0, 3)), ["A", "B", "C"])
        self.assertListEqual(ids(paginate(self.ordered, 1, 3)), ["D"])
        self.assertListEqual(ids(paginate(self.ordered, 2, 3)), [])

    def test_negative_zero_and_bool_page_sizes_are_rejected(self):
        for invalid_size in (0, -1, False, True):
            with self.subTest(invalid_size=invalid_size):
                with self.assertRaises(ValueError):
                    paginate(self.ordered, 0, invalid_size)

    def test_invalid_page_numbers_are_rejected(self):
        for invalid_number in (-1, False, True, 1.5):
            with self.subTest(invalid_number=invalid_number):
                with self.assertRaises(ValueError):
                    paginate(self.ordered, invalid_number, 2)


if __name__ == "__main__":
    unittest.main()
